CREATE TABLE platform_operator(user_id uuid PRIMARY KEY REFERENCES app_user(id),provisioned_by varchar(255) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_preference(user_id uuid PRIMARY KEY REFERENCES app_user(id),push_enabled boolean NOT NULL DEFAULT true);
CREATE TABLE platform_notification(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user(id),kind varchar(30) NOT NULL,event_id uuid REFERENCES club_event(id),group_key varchar(255),body text NOT NULL,item_count integer NOT NULL DEFAULT 1,is_read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX platform_inbox_idx ON platform_notification(user_id,created_at DESC);
CREATE UNIQUE INDEX platform_social_group_idx ON platform_notification(user_id,group_key) WHERE kind='SOCIAL' AND group_key IS NOT NULL AND NOT is_read;
CREATE TABLE platform_outbox(id uuid PRIMARY KEY,notification_id uuid NOT NULL REFERENCES platform_notification(id),status varchar(30) NOT NULL CHECK(status IN ('PENDING','RETRY','SUPPRESSED','SENT')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),last_error varchar(255),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX platform_outbox_due_idx ON platform_outbox(next_attempt_at) WHERE status IN ('PENDING','RETRY');
CREATE TABLE platform_level(id uuid PRIMARY KEY,event_id uuid NOT NULL REFERENCES club_event(id),user_id uuid NOT NULL REFERENCES app_user(id),role varchar(20) NOT NULL CHECK(role IN ('PARTICIPANT','HOST')),outcome varchar(30) NOT NULL,delta integer NOT NULL,reason text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,user_id,role));
CREATE TABLE platform_level_audit(id uuid PRIMARY KEY,level_id uuid NOT NULL REFERENCES platform_level(id),outcome varchar(30) NOT NULL,delta integer NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_case(id uuid PRIMARY KEY,version bigint NOT NULL DEFAULT 0,case_type varchar(30) NOT NULL,club_id uuid REFERENCES club(id),event_id uuid REFERENCES club_event(id),requester_id uuid NOT NULL REFERENCES app_user(id),target_user_id uuid NOT NULL REFERENCES app_user(id),route varchar(20) NOT NULL CHECK(route IN ('CLUB','HOST','OWNER','OPERATOR')),status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','PROGRESS','RESOLVED')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),activity_at timestamptz NOT NULL DEFAULT now(),reminded boolean NOT NULL DEFAULT false);
CREATE INDEX platform_case_queue_idx ON platform_case(route,status,activity_at);
CREATE TABLE platform_case_history(id uuid PRIMARY KEY,case_id uuid NOT NULL REFERENCES platform_case(id),actor_id uuid REFERENCES app_user(id),action varchar(40) NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_restriction(user_id uuid PRIMARY KEY REFERENCES app_user(id),case_id uuid NOT NULL REFERENCES platform_case(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE platform_case ADD COLUMN content_id uuid, ADD COLUMN content_type varchar(20) CHECK(content_type IN ('POST','COMMENT','MESSAGE'));
ALTER TABLE platform_case ADD COLUMN financial_dispute_id uuid REFERENCES finance_dispute(id), ADD COLUMN handler_id uuid REFERENCES app_user(id), ADD COLUMN assigned_at timestamptz, ADD COLUMN content_snapshot text;
CREATE INDEX platform_case_dispute_assignment ON platform_case(financial_dispute_id,handler_id) WHERE financial_dispute_id IS NOT NULL;
CREATE TABLE platform_push_device(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user(id),token varchar(4096) UNIQUE,platform varchar(10) NOT NULL CHECK(platform IN ('ANDROID','IOS','WEB')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE INDEX platform_push_device_owner ON platform_push_device(user_id) WHERE revoked_at IS NULL;
CREATE TABLE platform_push_delivery(outbox_id uuid NOT NULL REFERENCES platform_outbox(id),device_id uuid NOT NULL REFERENCES platform_push_device(id),status varchar(20) NOT NULL CHECK(status IN ('RETRY','SENT','INVALID')),attempts integer NOT NULL DEFAULT 0,last_error varchar(100),provider_message_id varchar(255),sent_at timestamptz,PRIMARY KEY(outbox_id,device_id));
CREATE TABLE platform_case_photo(case_id uuid NOT NULL REFERENCES platform_case(id),file_id uuid NOT NULL,position integer NOT NULL CHECK(position>=0),PRIMARY KEY(case_id,file_id),UNIQUE(case_id,position));
CREATE INDEX platform_case_photo_file ON platform_case_photo(file_id);
